#include "../src/game/stage2_actors.hpp"
int main(int argc,char**argv){if(argc!=2)return 1;shin::AssetStore a(argv[1]);shin::MapData map{100,100,{}};map.cells.resize(10000,{-1,-1,-1,0,0});shin::AppImage blocks{32,32,std::vector<unsigned char>(1024,0)};shin::PlayerPayload p;shin::initialize_player_payload(p,300,100);shin::game::Stage2Actors actors(a,map,blocks,p);if(!actors.spawn(31,100,100,1)||!actors.spawn(36,200,100,2)||!actors.spawn(32,400,100,3)||actors.spawn(1,0,0,4))return 2;shin::IndexedSurface f(640,480,254);for(int i=0;i<240;++i)actors.tick(0,0,f);if(actors.projectiles.size()!=2||actors.projectiles[0].callback!=0x4366b0||actors.projectiles[1].callback!=0x402440)return 3;actors.spawn(31,100,100,4);for(auto*e:actors.targets())if(!actors.hurt(*e))return 4;for(int i=0;i<25;++i)actors.tick(0,0,f);if(actors.targets().size()!=1||actors.defeated_count!=2)return 5;for(int i=0;i<9;++i){auto targets=actors.targets();if(targets.size()!=1||!actors.hurt(*targets[0]))return 6;for(int j=0;j<22;++j)actors.tick(0,0,f);}return actors.boss_defeated&&actors.targets().empty()?0:7;}

